/bin/bash -lc "ssh -o BatchMode=yes SeetaCloud '/root/miniconda3/bin/python - <<\"PY\"
import json, os, hashlib, numpy as np, sys
base=\"/root/ec_hte\"
files=[\"mvp/directed_dgp_config.json\",\"mvp/ec_hte_directed_stress_test.py\",\"mvp/ec_hte_oracle_bound.py\",\"mvp/run_directed_stability.py\",\"mvp/ec_hte_directed_seed_sweep.py\"]
hashes={}
for rel in files:
    p=os.path.join(base,rel)
    with open(p,\"rb\") as f: hashes[\"/root/ec_hte/\"+rel]=hashlib.sha256(f.read()).hexdigest()
with open(os.path.join(base,\"mvp/directed_dgp_config.json\")) as f: cfg=json.load(f)
k6=np.array(cfg[\"k6\"][\"confusion_rows_p_observed_given_true\"], dtype=float)
outs={}
for exp in [\"stress_global_worse_region_001\",\"oracle_confusion_upper_bound_001\",\"stability_seed_reps_001\"]:
    root=os.path.join(base,\"results\",exp,\"smoke_c008\")
    paths=[]
    for cur, dirs, fs in os.walk(root):
        for name in fs:
            paths.append(os.path.join(cur,name))
    outs[exp]=sorted(paths)
print(json.dumps({\"env\":{\"python\":sys.version.split()[0],\"numpy\":np.__version__},\"hashes\":hashes,\"k6_row_sums\":[float(x) for x in k6.sum(axis=1)],\"k6_asymmetric\":bool(not np.allclose(k6,k6.T)),\"outputs\":outs}, indent=2))
PY'"
